/**
 * LOT Red-Team Security Gatekeeper & Quality Auditor Agent
 * Inspired by MetaGPT SOPs and Microsoft Agent Framework (MAF).
 * Audits code generated by Swarm agents for OWASP vulnerabilities, secret leaks, and memory leaks before workspace commit.
 */

export interface SecurityAuditIssue {
  severity: "critical" | "high" | "medium" | "low";
  rule: string;
  description: string;
  lineSnippet?: string;
}

export interface SecurityAuditReport {
  passed: boolean;
  score: number; // 0 - 100
  issues: SecurityAuditIssue[];
  summary: string;
}

export function auditCodeSecurity(code: string): SecurityAuditReport {
  const issues: SecurityAuditIssue[] = [];

  // 1. Secret Key & Token Leak Detection
  const secretPatterns = [
    { pattern: /(sk-[a-zA-Z0-9]{32,})/, rule: "OpenAI Secret Key Leak", severity: "critical" as const },
    { pattern: /(ghp_[a-zA-Z0-9]{36})/, rule: "GitHub Personal Access Token Leak", severity: "critical" as const },
    { pattern: /(eyJh[a-zA-Z0-9_-]{20,}\.eyJh[a-zA-Z0-9_-]{20,})/, rule: "Hardcoded JWT Token Leak", severity: "high" as const },
    { pattern: /password\s*=\s*['"][^'"]{4,}['"]/i, rule: "Hardcoded Plaintext Password", severity: "high" as const },
  ];

  for (const { pattern, rule, severity } of secretPatterns) {
    const match = code.match(pattern);
    if (match) {
      issues.push({
        severity,
        rule,
        description: `Potential hardcoded secret discovered: ${match[0].slice(0, 8)}...`,
        lineSnippet: match[0].slice(0, 30),
      });
    }
  }

  // 2. SQL Injection Detection
  if (/(SELECT|INSERT|UPDATE|DELETE).*\+.*req\.(body|query|params)/i.test(code) || /query\(`SELECT.*?\$\{/i.test(code)) {
    issues.push({
      severity: "critical",
      rule: "SQL Injection Vulnerability",
      description: "Direct string concatenation into raw SQL queries detected. Use parameterized queries or ORM bindings.",
    });
  }

  // 3. React XSS Detection
  if (/dangerouslySetInnerHTML\s*=\s*\{\s*\{\s*__html:\s*(req|body|content|user)/i.test(code)) {
    issues.push({
      severity: "high",
      rule: "Cross-Site Scripting (XSS)",
      description: "Unsanitized user input rendered into dangerouslySetInnerHTML. Sanitize via DOMPurify.",
    });
  }

  // 4. Infinite Loop or Memory Leak Detection
  if (/setInterval\([^)]+\)/.test(code) && !/clearInterval/.test(code) && code.includes("useEffect")) {
    issues.push({
      severity: "medium",
      rule: "React Memory Leak",
      description: "setInterval invoked inside useEffect without cleanup function returning clearInterval.",
    });
  }

  const criticalCount = issues.filter((i) => i.severity === "critical").length;
  const highCount = issues.filter((i) => i.severity === "high").length;
  const passed = criticalCount === 0 && highCount === 0;

  const penalty = criticalCount * 40 + highCount * 25 + issues.length * 5;
  const score = Math.max(0, 100 - penalty);

  return {
    passed,
    score,
    issues,
    summary: passed
      ? "Security Audit: 0 Critical Vulnerabilities. Safe for workspace application."
      : `Security Audit: ${issues.length} potential vulnerabilities detected. Manual inspection required.`,
  };
}
